import grpc
from concurrent import futures
import urllib.request
import urllib.parse
from urllib.parse import urlparse
import json
import re

import service_pb2
import service_pb2_grpc

# Internal service registry for microservice discovery
SERVICE_REGISTRY = {
    "auth": "http://auth-service.internal:8080",
    "billing": "http://billing-service.internal:8080",
    "notifications": "http://notifications-service.internal:8080",
}

BLOCKED_HOSTS = ["metadata.google.internal", "169.254.169.254"]

def is_safe_redirect(url):
    """Validate redirect targets - blocks known metadata endpoints"""
    parsed = urlparse(url)
    if parsed.hostname in BLOCKED_HOSTS:
        return False
    if parsed.scheme not in ('http', 'https', ''):
        return False
    # Block obvious private ranges
    if parsed.hostname and parsed.hostname.startswith('127.'):
        return False
    return True

def resolve_service_url(service_name, path=""):
    """Resolve internal service URL from registry"""
    base = SERVICE_REGISTRY.get(service_name)
    if base:
        return f"{base}/{path}"
    return None

class WebhookServicer(service_pb2_grpc.WebhookServiceServicer):

    def SendWebhook(self, request, context):
        """Send webhook to configured endpoint with redirect following"""
        target_url = request.url

        # Validate initial URL
        if not is_safe_redirect(target_url):
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            context.set_details("Blocked destination")
            return service_pb2.WebhookResponse(status="blocked")

        try:
            # Follow redirects manually to validate each hop
            max_redirects = 5
            current_url = target_url

            for i in range(max_redirects):
                req = urllib.request.Request(current_url, method='GET')
                req.add_header('User-Agent', 'InternalWebhookService/1.2')

                opener = urllib.request.build_opener(
                    urllib.request.HTTPRedirectHandler()
                )
                response = opener.open(req, timeout=5)

                # If we got a final response, return it
                if response.status in (200, 201, 202):
                    body = response.read(4096).decode('utf-8', errors='replace')
                    return service_pb2.WebhookResponse(
                        status="delivered",
                        response_body=body
                    )

                # Handle redirect
                redirect_url = response.getheader('Location')
                if redirect_url:
                    # Resolve relative URLs
                    redirect_url = urllib.parse.urljoin(current_url, redirect_url)

                    # Validate redirect target
                    if not is_safe_redirect(redirect_url):
                        return service_pb2.WebhookResponse(status="redirect_blocked")

                    current_url = redirect_url
                else:
                    break

            return service_pb2.WebhookResponse(status="too_many_redirects")

        except Exception as e:
            return service_pb2.WebhookResponse(
                status="error",
                response_body=str(e)
            )

    def ProxyServiceCall(self, request, context):
        """Proxy calls to internal services - used by API gateway"""
        resolved = resolve_service_url(request.service_name, request.path)
        if not resolved:
            # Fallback: allow direct URL if provided (for custom integrations)
            if request.direct_url:
                resolved = request.direct_url
            else:
                context.set_code(grpc.StatusCode.NOT_FOUND)
                return service_pb2.ProxyResponse(status="not_found")

        try:
            req = urllib.request.Request(resolved)
            resp = urllib.request.urlopen(req, timeout=3)
            body = resp.read(8192).decode('utf-8', errors='replace')
            return service_pb2.ProxyResponse(status="ok", body=body)
        except Exception as e:
            return service_pb2.ProxyResponse(status="error", body=str(e))


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    service_pb2_grpc.add_WebhookServiceServicer_to_server(
        WebhookServicer(), server
    )
    server.add_insecure_port('[::]:50051')
    server.start()
    print("Webhook gRPC service started on :50051")
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
